export async function POST(req: Request) {
  const event = await verifyAndParse(req);   // reject bad signatures with 400
  const inserted = await db.query(
    'INSERT INTO events (id, type, payload) VALUES ($1, $2, $3) ON CONFLICT (id) DO NOTHING RETURNING id',
    [event.id, event.type, event]
  );
  if (inserted.rowCount === 0) return new Response('duplicate', { status: 200 });
  await processEvent(event);
  return new Response('ok', { status: 200 });
}

async function handleToolCall(call) {
  if (call.name !== 'send_email') throw new Error('Unknown tool');
  const args = SendEmailArgs.parse(call.arguments);            // schema validation
  if (!isKnownClient(args.to)) return { error: 'Recipient not allowed' };
  const approved = await requestApproval({ tool: call.name, args }); // human in the loop
  await auditLog.write({ call, approved });
  if (!approved) return { status: 'rejected_by_user' };
  return sendEmail(args);
}
